//! Managed collection menu/read model and staged modal. No filesystem calls.
use super::{Intent,modal_footer::{self,Action as Button}};
use eframe::egui;
use skylive_core::Session;
use skylive_host::collection_library::{EntryId,View};
use std::{path::PathBuf,sync::Arc};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct Token{pub session:u64,pub revision:u64,pub serial:u64}
#[derive(Clone)]pub enum Action{Refresh{session:u64},Create{duplicate:bool},Remove,Switch{session:u64,revision:u64,id:EntryId},Confirm{token:Token,name:String},Cancel(Token)}
pub struct Draft{pub token:Token,pub name:String,pub duplicate:bool,pub removing:bool,pub source_path:Option<PathBuf>,pub error:Option<String>}
#[derive(Clone,Default)]struct Menu{view:Option<Arc<View>>,active:Option<PathBuf>,session:u64,problem:Option<String>}
const MENU:&str="managed-collection-menu";
pub fn install(ctx:&egui::Context,owner:&Session,view:Option<Arc<View>>,active:Option<PathBuf>,problem:Option<String>){ctx.data_mut(|data|data.insert_temp(egui::Id::new(MENU),Menu{view,active,session:owner.identity(),problem}));}
pub fn can_remove(ctx:&egui::Context,owner:&Session)->bool{ctx.data(|data|data.get_temp::<Menu>(egui::Id::new(MENU))).is_some_and(|state|state.session==owner.identity()&&state.view.as_ref().is_some_and(|view|view.writable&&view.entries.len()>=2&&view.entries.iter().any(|entry|view.path_for(entry.id).as_ref()==state.active.as_ref())))}
pub fn menu(ui:&mut egui::Ui,owner:&Session,intents:&mut Vec<Intent>){let state=ui.ctx().data(|data|data.get_temp::<Menu>(egui::Id::new(MENU))).unwrap_or_default();ui.menu_button(crate::i18n::tr(ui,"Managed collections"),|ui|{if state.session!=owner.identity()||state.view.is_none(){ui.label(crate::i18n::tr(ui,"Refresh to load the managed collection library."));}else if let Some(view)=&state.view{if view.entries.is_empty(){ui.label(crate::i18n::tr(ui,"The managed library is empty. Use New or Duplicate to create an owned collection."));}let query_id=ui.id().with("collection-search");let mut query=ui.ctx().data_mut(|data|data.get_temp::<String>(query_id)).unwrap_or_default();ui.add(egui::TextEdit::singleline(&mut query).char_limit(64).hint_text(crate::i18n::tr(ui,"Search collections…"))).on_hover_text(crate::i18n::tr(ui,"Search managed collections by their saved names."));ui.ctx().data_mut(|data|data.insert_temp(query_id,query.clone()));let query=query.to_lowercase();egui::ScrollArea::vertical().max_height(240.0).show(ui,|ui|{for entry in &view.entries{if !query.is_empty()&&!entry.name.to_lowercase().contains(&query){continue;}let selected=view.path_for(entry.id).as_ref()==state.active.as_ref();if ui.selectable_label(selected,&entry.name).on_hover_text(crate::i18n::tr(ui,"Load this managed collection after resolving unsaved changes. Sources retain their document-local identities.")).clicked(){intents.push(Intent::CollectionLibrary(Action::Switch{session:owner.identity(),revision:owner.snapshot().revision(),id:entry.id}));ui.close_menu();}}});if !view.writable{ui.label(crate::i18n::tr(ui,"Managed collection writes are available on Windows; this host can inspect and open existing entries."));}}if let Some(error)=&state.problem{ui.label(crate::i18n::tr(ui,"Library information"));egui::ScrollArea::vertical().id_salt("library-error").max_height(88.0).show(ui,|ui|{ui.label(error);});}ui.separator();if ui.button(crate::i18n::tr(ui,"Refresh collections")).on_hover_text(crate::i18n::tr(ui,"Read the actual managed library index on the I/O worker. External files are not adopted.")).clicked(){intents.push(Intent::CollectionLibrary(Action::Refresh{session:owner.identity()}));ui.close_menu();}}).response.on_hover_text(crate::i18n::tr(ui,"Switch between saved app-managed collections; arbitrary Open files stay external."));}
pub fn show(ctx:&egui::Context,draft:&mut Draft,owner:&Session,busy:bool)->Option<Action>{let mut action=None;let fresh=draft.token.session==owner.identity()&&draft.token.revision==owner.snapshot().revision()&&!owner.is_closed();let valid=!draft.name.trim().is_empty()&&draft.name.len()<=256&&!draft.name.chars().any(char::is_control);let response=egui::Modal::new(egui::Id::new(("managed-collection-dialog",draft.token.session,draft.token.serial))).show(ctx,|ui|{ui.set_width(680.0_f32.min((ctx.screen_rect().width()-48.0).max(120.0)));ui.heading(crate::i18n::tr(ui,if draft.removing{"Remove managed collection"}else if draft.duplicate{"Duplicate scene collection"}else{"New managed collection"}));let actions=[Button::new(if draft.removing{"Switch and remove"}else{"Create and switch"},fresh&&!busy&&(draft.removing||valid),"Resolve dirty-document choices before publishing any managed file operation."),Button::new("Cancel",!busy,"Keep the current collection and create no new artifact.")];let height=(ctx.screen_rect().height()-modal_footer::required_height(ui,&actions)-110.0).max(40.0);egui::ScrollArea::vertical().id_salt("managed-collection-body").max_height(height).show(ui,|ui|{if draft.removing{ui.label(&draft.name);if let Some(path)=&draft.source_path{ui.label(path.display().to_string());}ui.label(crate::i18n::tr(ui,"Another saved managed collection opens first. The current owned file is removed from the library only after successful switching and is retained in the recovery folder."));ui.label(crate::i18n::tr(ui,"External Open files are never deleted. The last managed collection cannot be removed."));}else{let label=ui.label(crate::i18n::tr(ui,"Collection name"));ui.add(egui::TextEdit::singleline(&mut draft.name).char_limit(256).desired_width(ui.available_width())).labelled_by(label.id).on_hover_text(crate::i18n::tr(ui,"Choose a unique name of 1–256 UTF-8 bytes without control characters."));ui.label(crate::i18n::tr(ui,if draft.duplicate{"Create an independent native copy of the reviewed current snapshot. Source shortcuts and saved projector targets keep their document-local IDs in a new session."}else{"Create a new managed native collection using the current profiles and installed preferences."}));ui.label(crate::i18n::tr(ui,"Existing dirty-document Save, Discard and Cancel choices run before a new file is created. Cancel creates no artifact."));}if !fresh{ui.colored_label(ui.visuals().error_fg_color,crate::i18n::tr(ui,"The collection draft is obsolete. Cancel and reopen it."));}if let Some(error)=&draft.error{ui.colored_label(ui.visuals().error_fg_color,crate::i18n::tr(ui,error));}});ui.separator();match modal_footer::show(ui,&actions){Some(0)=>action=Some(Action::Confirm{token:draft.token,name:draft.name.clone()}),Some(1)=>action=Some(Action::Cancel(draft.token)),_=>{}}});if response.should_close()&&!busy{action=Some(Action::Cancel(draft.token));}action}
